
<section>
    <div
        id="postBar"
        class="postBar"
    >
        <PostBarScrollButtons/>
        <div
            id="postsContainer"
            class="w-full flex items-start overflow-x-auto"
        >
            <post
                v-for="(selectedPostId, i) in selectedPostIds"
                :id="`post-${i}`"
                :key="selectedPostId"
                class="m-2 p-2"
                :post="posts[selectedPostId]"
            >
            </post>
        </div>
    </div>
</section>
